  ],
  "health_port": 19080,
  "verbose": false
}

{
  "mode": "client",
  "profile": "balanced",
  "transport": "tcpmux",
  "psk": "LOCAL_PSK",
  "encryption": {
    "enabled": true,
    "algorithm": "chacha20-poly1305"
  },
  "paths": [
    {
      "transport": "tcpmux",
      "addr": "SERVER_A_IP:4000",
      "connection_pool": 1,
      "retry_interval": 3,
      "dial_timeout": 10
